export function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
}

export function buildDetailerSite(input = {}) {
  const esc = escapeHtml;
  const palettes = {blue:['#153a72','#e9f1ff'],green:['#16463b','#e7f1ea'],clay:['#723f30','#f7eee7']};
  const [accent,tint] = palettes[input.theme] || palettes.blue;
  const name = String(input.name || 'Your Detail Co.').slice(0,100);
  const city = String(input.city || 'Your service area').slice(0,100);
  const rawEmail = String(input.email || '').trim();
  const email = /^[^\s@<>"']+@[^\s@<>"']+\.[^\s@<>"']+$/.test(rawEmail) ? rawEmail : '';
  const phone = String(input.phone || '').replace(/[^+\d]/g,'').slice(0,18);
  const packages = Array.isArray(input.packages) ? input.packages.slice(0,3) : [
    {name:'Exterior refresh',price:'From $75',detail:'Wash, wheels, and a clean finish.'},
    {name:'Interior reset',price:'From $125',detail:'Vacuum, surfaces, and interior care.'},
    {name:'Full detail',price:'From $199',detail:'Interior and exterior, tailored to your vehicle.'}
  ];
  const contact = email ? `<a class="button" href="mailto:${esc(email)}?subject=Detailing%20quote%20request">Request a quote</a>` : phone ? `<a class="button" href="tel:${esc(phone)}">Call for a quote</a>` : '<p class="contact-note">Add a business email or phone before publishing this draft.</p>';
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(name)} | Mobile detailing in ${esc(city)}</title><meta name="description" content="Explore ${esc(name)} services and request a detailing quote in ${esc(city)}."><style>
  *{box-sizing:border-box}body{margin:0;color:#182a35;background:#fcfcf9;font:16px/1.6 system-ui,sans-serif}a{color:inherit}.wrap{max-width:1060px;margin:auto;padding:0 28px}.draft{padding:8px 16px;text-align:center;background:${tint};font-size:12px}header{padding:22px 0;border-bottom:1px solid #e1e5df}.nav{display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{font-weight:750;font-size:20px;overflow-wrap:anywhere}.nav a{font-size:14px}.hero{padding:76px 0 64px;display:grid;grid-template-columns:1.2fr .8fr;gap:40px;align-items:center}.eyebrow{color:${accent};font-size:12px;font-weight:750;letter-spacing:.12em;text-transform:uppercase}h1{font-size:clamp(36px,6vw,64px);line-height:1.08;letter-spacing:-.05em;margin:18px 0 22px;overflow-wrap:anywhere}h2{font-size:30px;line-height:1.2;letter-spacing:-.03em}.muted{color:#53616a}.button{display:inline-block;background:${accent};color:white;text-decoration:none;padding:14px 23px;border-radius:7px;font-weight:650;margin-top:15px}.art{background:${tint};border-radius:48% 48% 12% 12%;min-height:280px;display:grid;place-items:center;padding:30px}.car{width:100%;max-width:300px;height:auto;color:${accent}}section{padding:30px 0 45px}.packages{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{border:1px solid #dfe5df;padding:24px;border-radius:10px;background:white;overflow-wrap:anywhere}.price{font-size:26px;color:${accent};font-weight:700}.contact{background:${tint};border-radius:12px;padding:30px}.contact-note{color:#5c6568;font-size:14px}footer{padding:30px 0;border-top:1px solid #e1e5df;font-size:13px}.draft-content{font-size:12px;color:#687270}a:focus-visible{outline:3px solid #d49432;outline-offset:5px}@media(max-width:650px){.hero{grid-template-columns:1fr;padding:40px 0;gap:20px}.art{min-height:190px;max-width:400px}.packages{grid-template-columns:1fr}.wrap{padding:0 20px}.nav{align-items:flex-start}.nav a{white-space:nowrap}}
  </style></head><body><div class="draft">Website draft. Confirm services, prices, contact details, and service area before publishing.</div><header><div class="wrap nav"><div class="brand">${esc(name)}</div><a href="#services">Explore services</a></div></header><main class="wrap"><div class="hero"><div><div class="eyebrow">Mobile detailing · ${esc(city)}</div><h1>A fresh start for your vehicle.</h1><p class="muted">Explore our detailing packages, then ask about your vehicle, location, and preferred appointment.</p>${contact}</div><div class="art"><svg class="car" viewBox="0 0 360 190" role="img" aria-label="Illustration of a clean car"><path d="M58 118 94 67Q104 52 128 52h105q22 0 37 24l24 42 25 10v27H40v-22z" fill="currentColor" opacity=".12"/><path d="m74 113 33-44h120q12 0 22 13l22 31z" fill="none" stroke="currentColor" stroke-width="4"/><path d="M39 129q12-13 29-13h220q31 0 35 24v20H39z" fill="none" stroke="currentColor" stroke-width="4"/><circle cx="94" cy="158" r="22" fill="#fcfcf9" stroke="currentColor" stroke-width="4"/><circle cx="272" cy="158" r="22" fill="#fcfcf9" stroke="currentColor" stroke-width="4"/><path d="m282 22 3 11 11 3-11 3-3 11-3-11-11-3 11-3z" fill="currentColor"/></svg></div></div><section id="services"><div class="eyebrow">Choose your starting point</div><h2>Care for the way you drive.</h2><div class="packages">${packages.map(p=>`<article class="card"><h3>${esc(p.name)}</h3><p class="price">${esc(p.price)}</p><p class="muted">${esc(p.detail)}</p></article>`).join('')}</div><p class="draft-content">Final scope and price depend on vehicle size and condition. Confirm details when requesting a quote.</p></section><section id="contact"><div class="contact"><h2>Tell us about your vehicle.</h2><p>Share your vehicle, the service you need, and your location in ${esc(city)}. We will confirm availability and a quote.</p>${contact}${email?`<p>${esc(email)}</p>`:''}${phone?`<p>${esc(input.phone)}</p>`:''}</div></section></main><footer><div class="wrap">${esc(name)} · ${esc(city)}</div></footer></body></html>`;
}
